function primeTally(limit) {
    let count = 0;
    for (let n = 2; n < limit; n++) {
        let prime = true;
        for (let d = 2; d * d <= n; d++) {
            if (n % d === 0) {
                prime = false;
                break;
            }
        }
        if (prime)
            count++;
    }
    return count;
}

function primeTally(limit) {
    if (limit < 3)
        return 0;
    const composite = new Uint8Array(limit);
    let count = 0;
    for (let n = 2; n < limit; n++) {
        if (composite[n])
            continue;
        count++;
        for (let multiple = n * n; multiple < limit; multiple += n)
            composite[multiple] = 1;
    }
    return count;
}
